Answer(`\boxed{}`):　```python
import numpy as np

class Defibrillator:
    def __init__(self):
        self.info_bytes = 100000

def control_defibrillators():
    num_defibrillators = 5
    total_info_bytes = 100000

    if total_info_bytes % num_defibrillators != 0:
        raise ValueError("The number of defibrillators must evenly divide the total info bytes.")

    info_bytes_per_defibrillator = total_info_bytes // num_defibrillators
    defibrillators = [Defibrillator() for _ in range(num_defibrillators)]
